def _class_getstate(obj):
    """Extract the state of a class for pickling.

    Returns a tuple of (clsdict, slotstate) where clsdict contains the class's
    __dict__ with inherited attributes filtered out, and slotstate contains
    special attributes that need to be restored at unpickling time.
    """
    clsdict = _extract_class_dict(obj)

    slotstate = {}

    # Special attributes that need to be preserved
    for attr_name in ["__module__", "__qualname__", "__doc__", "__annotations__"]:
        if hasattr(obj, attr_name):
            slotstate[attr_name] = getattr(obj, attr_name)

    # Hack to circumvent non-predictable memoization caused by string interning.
    # See the inline comment in _class_setstate for details.
    clsdict = {"".join(k): v for k, v in clsdict.items()}

    return clsdict, slotstate

def _enum_getstate(obj):
    clsdict, slotstate = _class_getstate(obj)

